import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int k = Integer.parseInt(firstLine[1]);
        String[] secondLine = br.readLine().split(" ");
        int[] numbers = new int[n];
        for (int i = 0; i < n; i++) {
            numbers[i] = Integer.parseInt(secondLine[i]);
        }
        int[] numbers_mod = new int[n];
        for (int i = 0; i < n; i++) {
            numbers_mod[i] = numbers[i] % k;
        }
        if (n == 1) {
            System.out.println(numbers_mod[0]);
            return;
        }
        int[] partA = Arrays.copyOfRange(numbers_mod, 0, n / 2);
        int[] partB = Arrays.copyOfRange(numbers_mod, n / 2, n);
        Set<Integer> setA = new HashSet<>();
        Set<Integer> setB = new HashSet<>();
        Set<Integer> tempSetB = new HashSet<>();

        for (int val : partA) {
            for (int prev : setA) {
                setB.add((prev + val) % k);
            }
            setA.add(val);
            for (int prev : setB) {
                setA.add(prev);
            }
            setB.clear();
        }

        for (int val : partB) {
            for (int prev : setB) {
                setB.add((prev + val) % k);
            }
            setB.addAll(setA);
        }

        List<Integer> listA = new ArrayList<>(setA);
        List<Integer> listB = new ArrayList<>(setB);
        Collections.sort(listA);
        Collections.sort(listB);

        int max_res = Math.max(Collections.max(listA), Collections.max(listB));
        int result = max_res;

        for (int s_elem : listA) {
            int target = k - 1 - s_elem;
            int idx = upperBound(listB, target);
            if (idx > 0) {
                int r = listB.get(idx - 1);
                int rt = listB.get(listB.size() - 1);
                int candidate1 = (r + s_elem) % k;
                int candidate2 = (s_elem + rt) % k;
                result = Math.max(result, Math.max(candidate1, candidate2));
            }
        }
        System.out.println(result);
    }

    private static int upperBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) <= key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}
